<script setup>
import { computed,defineAsyncComponent,onMounted,reactive,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Button } from 'ant-design-vue'
import { useDocumentRead } from './documentState.js'
import ReadState from './ReadState.vue'
import Facts from './Facts.vue'
import './document.css'
const StrategyPanel=defineAsyncComponent(()=>import('./StrategyPanel.vue')),TaskPanel=defineAsyncComponent(()=>import('./TaskPanel.vue')),ArtifactPanel=defineAsyncComponent(()=>import('./ArtifactPanel.vue')),ChunksPanel=defineAsyncComponent(()=>import('./ChunksPanel.vue')),ParsePanel=defineAsyncComponent(()=>import('./ParsePanel.vue')),ExplorerPanel=defineAsyncComponent(()=>import('./ExplorerPanel.vue'))
const props=defineProps({documentId:String}),route=useRoute(),router=useRouter(),detail=useDocumentRead('detail')
const tabs=[['overview','文档概览'],['strategy','策略方案'],['tasks','任务与日志'],['artifacts','解析产物'],['chunk','分块'],['rag','解析工作台'],['explorer','产物与关系']]
const tab=computed(()=>{if(route.query.showParseProgress==='1'||route.query.section==='execution')return 'tasks';if(tabs.some(([key])=>key===route.query.section))return route.query.section;if(Object.keys(route.query).some(k=>k.startsWith('highlight')))return 'rag';return 'overview'})
const taskId=ref(''),taskKind=ref(undefined)
function applyRouteTask(){if(route.query.section==='execution'&&route.query.showParseProgress!=='1'){taskKind.value='build';taskId.value=typeof route.query.indexTaskId==='string'?route.query.indexTaskId:''}else if(typeof route.query.parseTaskId==='string'){taskKind.value='parse';taskId.value=route.query.parseTaskId}else if(typeof route.query.indexTaskId==='string'){taskKind.value='build';taskId.value=route.query.indexTaskId}}
applyRouteTask()
watch(()=>[route.query.parseTaskId,route.query.indexTaskId,route.query.section,route.query.showParseProgress],applyRouteTask);
const browseMemory=reactive({}),returnEntry=ref(null)
function memoryFor(kind){const key=taskScope.value+':'+kind;return browseMemory[key] ||= {}}
function navigate(section){router.push({query:{...route.query,section,showParseProgress:undefined,locatePage:undefined,locateOverlay:undefined,browseFrom:undefined}})}
function returnToExplorer(){if(returnEntry.value&&window.history.state?.back===returnEntry.value)router.back();else router.replace({query:{...route.query,section:'explorer',locatePage:undefined,locateOverlay:undefined,browseFrom:undefined,showParseProgress:undefined}})}
function build(task){taskId.value=typeof task==='string'?task:'';taskKind.value='build';router.replace({query:{...route.query,section:'tasks',showParseProgress:undefined,parseTaskId:undefined,indexTaskId:taskId.value||undefined}})}
function locate(node){returnEntry.value=router.resolve({path:route.path,query:route.query}).href;router.push({query:{...route.query,section:'rag',showParseProgress:undefined,browseFrom:'explorer',locatePage:String(node.pageNo),locateOverlay:node.overlayId || undefined}})}
function read(){detail.read({documentId:props.documentId})}
const taskScope=computed(()=>`${route.query.parseTaskId||''}:${route.query.indexTaskId||''}`)
watch(taskScope,()=>{for(const key of Object.keys(browseMemory))delete browseMemory[key];returnEntry.value=null})
const summary=computed(()=>Object.fromEntries(Object.entries(detail.data.value||{}).filter(([key])=>['originalFileName','knowledgeBaseName','fileTypeName','fileSize','charCount','tokenCount','createTime','editTime','parseErrorMsg'].includes(key))))
const back=computed(()=>({path:'/admin/documents',query:{q:typeof route.query.listQ==='string'?route.query.listQ:undefined,page:typeof route.query.listPage==='string'?route.query.listPage:undefined,size:typeof route.query.listSize==='string'?route.query.listSize:undefined}}))
onMounted(read)
</script>
<template><section class="admin-next-doc-workspace" aria-labelledby="document-title"><div class="admin-next-doc-row"><div><RouterLink :to="back" class="admin-next-doc-back">← 文档列表</RouterLink><h1 id="document-title">{{ detail.data.value?.documentName || '文档详情' }}</h1><p class="admin-next-doc-id">文档 ID {{ documentId }}</p></div><Button :disabled="detail.loading.value" @click="read">刷新文档</Button></div><ReadState :state="detail" label="文档" @retry="read" /><template v-if="detail.data.value"><div class="admin-next-doc-status" aria-label="文档状态"><span>解析：{{ detail.data.value.parseStatusName || '未记录' }}</span><span>策略：{{ detail.data.value.strategyStatusName || '未记录' }}</span><span>索引：{{ detail.data.value.indexStatusName || '未记录' }}</span></div><nav class="admin-next-doc-tabs" aria-label="文档工作台"><Button v-for="[key,label] in tabs" :key="key" :type="tab===key?'primary':'text'" :aria-current="tab===key?'page':undefined" @click="navigate(key)">{{ label }}</Button></nav><section v-if="tab==='overview'" class="admin-next-doc-panel"><h2>文档摘要</h2><Facts :value="summary" :labels="{documentId:'文档 ID',documentName:'文档名称',originalFileName:'原文件名',knowledgeBaseName:'所属知识库',knowledgeBaseId:'知识库 ID',fileTypeName:'文件类型',fileSize:'文件大小（B）',charCount:'字符数',tokenCount:'Token 数',parseStatusName:'解析状态',strategyStatusName:'策略状态',indexStatusName:'索引状态',currentPlanId:'当前方案 ID',latestTaskId:'最新任务 ID',latestTaskTypeName:'最新任务类型',latestTaskStatusName:'最新任务状态',createTime:'创建时间',editTime:'更新时间',parseErrorMsg:'解析错误'}" /><details><summary>查看技术元数据</summary><Facts :value="detail.data.value" /></details></section><StrategyPanel v-if="tab==='strategy'" :document="detail.data.value" @changed="read" @build="build" /><TaskPanel :key="taskKind+':'+taskId" v-if="tab==='tasks'" :document="detail.data.value" :initial-task-id="taskId" :initial-kind="taskKind" @finished="read" @strategy="navigate('strategy')" /><ArtifactPanel :memory="memoryFor('artifacts')" :key="taskScope" v-if="tab==='artifacts'" :document-id="documentId" :task-id="typeof route.query.parseTaskId==='string'?route.query.parseTaskId:undefined" /><ChunksPanel :memory="memoryFor('chunk')" :key="taskScope" :task-id="typeof route.query.indexTaskId==='string'?route.query.indexTaskId:undefined" v-if="tab==='chunk'" :document-id="documentId" /><ParsePanel :memory="memoryFor('rag')" @return-explorer="returnToExplorer" :key="taskScope+':'+(route.query.locatePage||'')+':'+(route.query.locateOverlay||'')" v-if="tab==='rag'" :document-id="documentId" /><ExplorerPanel :memory="memoryFor('explorer')" :key="taskScope" v-if="tab==='explorer'" :document-id="documentId" @locate="locate" /></template></section></template>
